def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]

    split_col = 7

    # Map top rows (0-5) to bottom rows (6-10)
    # For each right-side column, if bottom row has 5, top row gets 1
    # Otherwise top row gets 4

    for r in range(min(rows, 6)):
        src_r = r + 6
        if src_r < rows:
            for c in range(split_col, cols):
                if grid[src_r][c] == 5:
                    output[r][c] = 1
                else:
                    output[r][c] = 4

    # Bottom rows stay the same

    return output
